const { Schema, model } = require('mongoose');

const applicationSchema = new Schema({
    // ID da aplicação, único
    applicationId: { type: String, required: true, unique: true },

    // Informações básicas
    name: { type: String, default: 'Sem nome' },
    description: { type: String },

    // Referência ao proprietário (usuário)
    owner: { type: String, required: true },

    // IDs relacionados
    hostId: { type: String },
    clientId: { type: String },

    // Status de compartilhamento e produto associado
    sharedClient: { type: Boolean, required: true, default: false },
    product: { type: Schema.Types.ObjectId, ref: 'products', required: true },

    // Timestamps
    createdAt: { type: Date, default: Date.now },
    lastRenovationAt: { type: Date, default: Date.now },
    nextRenewalAt: { type: Date, default: () => new Date(Date.now() + 30 * 24 * 60 * 60 * 1000) }, // 30 dias a partir de agora

    // Servidores disponíveis
    availableServers: { type: Array },
    maxAvailableServers: { type: Number, default: 0 },

    // Notificações
    lastNotificationAt: { type: Date, default: Date.now },
    notificationsSent: [{
        timestamp: { type: Date, default: Date.now }
    }]
}, { timestamps: true });

module.exports = applicationSchema

const { Schema, model } = require('mongoose');

const priceOptionSchema = new Schema({
    isActive: { type: Boolean, default: false },
    price: { type: Number, default: 0 }
}, { _id: false });

const embedDetailsSchema = new Schema({
    banner: { type: String, default: null },
    description: { type: String, default: '' },
    title: { type: String, default: 'Título do Produto' },
    color: { type: String, default: '#FFFFFF' },
    preview: { type: String, default: null },
}, { _id: false });

const productSchema = new Schema({
    productName: { type: String, required: true },
    price: {
        mensal: { type: priceOptionSchema, default: () => ({}) },
        quinzenal: { type: priceOptionSchema, default: () => ({}) },
        semanal: { type: priceOptionSchema, default: () => ({}) },
        embed: { type: embedDetailsSchema, default: () => ({}) }
    }
}, { timestamps: true });

module.exports = productSchema;


